const SOLUTIONS = new Set(['web_catalogo', 'chatbot_whatsapp_ia', 'pack_web_chatbot', 'asesor']);

function clean(value) {
  return String(value == null ? '' : value).replace(/\s+/g, ' ').trim();
}

function normalized(value) {
  return clean(value).normalize('NFD').replace(/[\u0300-\u036f]/g, '').toLowerCase();
}

function pickMatch(text, expressions) {
  for (const expression of expressions) {
    const match = text.match(expression);
    if (match) return clean(match[1] || match[0]);
  }
  return '';
}

// Mucha gente escribe en mayúsculas desde el móvil. Guardarlo tal cual deja el
// CRM ilegible y hace que el resumen le devuelva sus propias palabras a gritos.
// Se conserva la mayúscula inicial y la de las siglas de dos o tres letras.
function sinGritos(valor) {
  const texto = String(valor == null ? '' : valor);
  const letras = texto.replace(/[^a-záéíóúüñA-ZÁÉÍÓÚÜÑ]/g, '');
  if (letras.length < 4) return texto;
  const mayusculas = texto.replace(/[^A-ZÁÉÍÓÚÜÑ]/g, '').length;
  if (mayusculas / letras.length < 0.7) return texto;
  const suave = texto.toLocaleLowerCase('es-CO');
  return suave.charAt(0).toLocaleUpperCase('es-CO') + suave.slice(1);
}

function canonicalBusiness(raw) {
  const value = normalized(raw);
  if (!value) return '';
  if (/ropa|moda|prendas|boutique|tienda/.test(value)) return 'tienda / retail';
  if (/restaurante|comidas?|cafeteria|panaderia/.test(value)) return 'gastronomía';
  if (/servicios?|consultoria|agencia/.test(value)) return clean(raw);
  return clean(raw).slice(0, 120);
}

function detectIntent(message, messageType) {
  const text = normalized(message);
  if (messageType && messageType !== 'text') return 'media';
  if (/^reset$|^reiniciar$|^borrar memoria$/.test(text)) return 'reset';
  if (/^activar luna$|^reactivar luna$|^volver con luna$/.test(text)) return 'activate';
  if (/^no molestar$|no me (?:escribas|contactes)|no quiero mensajes|darme de baja/.test(text)) return 'opt_out';
  if (/\b(?:que eres|quien eres|eres (?:un |una )?(?:bot|robot|maquina|humano|humana|persona|real)|con quien (?:hablo|estoy hablando)|que (?:puedes|sabes) hacer|para que sirves|quien habla)\b/.test(text)) return 'about';
  if (/\bno (?:tengo|uso|manejo|quiero dar|quiero darte)\s+(?:mi\s+|un\s+|el\s+)?(?:correo|email|e-mail|mail)\b|\bprefiero no (?:dar|darte|compartir|poner)\b|^sin correo\b|\bno te (?:doy|voy a dar) (?:mi )?(?:correo|email)\b/.test(text)) return 'no_email';
  if (/\b(?:asesor|humano|persona|hablar con alguien)\b/.test(text)) return 'handoff';
  if (/\b(?:que incluye|que incluyen|que trae|que traen|que abarca|que contiene|que cubre)\b|^incluye\??$/.test(text)) return 'includes';
  if (/\b(?:reunion|videollamada|asesoria)\b|\b(?:agendar|agendemos|agendamos|coordinar|programar|separar)\s+(?:una?\s+|el\s+|un\s+)?(?:reunion|llamada|cita|videollamada|demo|espacio|horario)\b|^(?:agendar|agenda|agendemos)\??$|\bhorarios? disponibles?\b/.test(text)) return 'appointment';
  if (/\b(?:propuesta|cotizacion|cotizar|armar los numeros)\b/.test(text)) return 'proposal';
  if (/\b(?:en cuanto tiempo|cuanto (?:se )?(?:demora|demoran|tarda|tardan)|cuanto (?:tiempo )?(?:toma|lleva)|tiempo de entrega|plazo de entrega|para cuando (?:lo )?(?:tienen|esta|estaria)|cuando (?:lo |me lo )?(?:entregan|tienen listo|estaria listo))\b/.test(text)) return 'timeline';
  if (/\b(?:descuento|descuentos|rebaja|rebajas|promocion|promociones|oferta especial|mas barato|precio especial|hacen precio|me lo dejan en)\b/.test(text)) return 'discount';
  if (/\b(?:donde (?:estan|queda|quedan|los ubico)|ubicados|ubicacion|de donde son|de que ciudad|tienen oficina|atienden en|trabajan en)\b/.test(text)) return 'location';
  if (/\b(?:precio|precios|cuanto (?:me |te |nos |le |les )?(?:cuesta|cuestan|vale|valen|sale|salen|es|seria|serian|saldria|costaria)|que (?:vale|precio)|valor|inversion|tarifa|cotizacion|cotizar)\b/.test(text)) return 'price';
  if (/\b(?:quiero el pack|quiero ambos|web y chatbot|chatbot y web)\b|^(?:si|sí)?[,\s]*(?:ambos|ambas|los dos|las dos)\b/.test(text)) return 'select_pack';
  if (/\b(?:solo chatbot|solamente chatbot)\b/.test(text)) return 'confirm_chatbot';
  if (/\b(?:solo web|solamente web|solo catalogo)\b/.test(text)) return 'confirm_web';
  if (/\b(?:necesito|quiero|busco)\b.*\bchatbot\b|^chatbot$/.test(text)) return 'select_chatbot';
  if (/\b(?:necesito|quiero|busco)\b.*\b(?:web|catalogo)\b|^(?:web|catalogo)$/.test(text)) return 'select_web';
  if (/^(?:menu|menú)$/.test(clean(message).toLowerCase())) return 'menu';
  if (/^(?:hola|buenas|buenos dias|buenas tardes|buenas noches|hey|holi|ola|que mas|quiubo)(?:\s+(?:hola|buenas|buenos dias|buenas tardes|buenas noches|que tal|como estas|como esta))?[\s!.]*$/.test(text)) return 'greeting';
  if (/^(?:muchas gracias|ok gracias|listo gracias|vale gracias|perfecto gracias|ya gracias|gracias)[\s!.]*$/.test(text)) return 'courtesy_close';
  if (/caro|costoso|muy alto/.test(text)) return 'objection_price_high';
  if (/lo voy a pensar|dejamelo pensar|necesito pensarlo/.test(text)) return 'objection_need_to_think';
  if (/solo (?:quiero )?informacion/.test(text)) return 'objection_only_information';
  if (/no tengo presupuesto|sin presupuesto/.test(text)) return 'objection_no_budget';
  if (/^(?:pues |la verdad |es que |mmm?|eh)?\s*(?:no (?:lo )?se|no sabria|ni idea|no estoy seguro|no estoy segura|no tengo claro|cualquiera|lo que sea|no se la verdad|no sabria decirte)(?:\s+la verdad)?[\s.,!]*$|^(?:pues )?no se,?\s*(?:algo|alguna cosa|lo que)\b/.test(text)) return 'dont_know';
  return 'general';
}

function extractFields(message, prior) {
  const raw = clean(message);
  const text = normalized(raw);
  const context = prior && typeof prior === 'object' ? prior : {};
  const fields = {};

  const emailMatch = raw.match(/[A-Z0-9._%+-]+@[A-Z0-9.-]+\.[A-Z]{2,}/i);
  if (emailMatch) fields.email = emailMatch[0].toLowerCase();

  const business = pickMatch(raw, [
    /(?:me dedico a|mi negocio es|tengo (?:una?|un)|vendo)\s+(.{2,100})/i,
    /(?:somos (?:una?|un))\s+(.{2,100})/i,
  ]);
  // El rubro es lo primero que dice la frase. Sin este corte, "somos una
  // clínica dental, necesito que agenden solas las citas porque..." entraba
  // entero en la columna business_type del CRM.
  const rubro = business ? clean(String(business).split(/[,;.]| y (?=[a-záéíóúñ])| porque | pero | que /i)[0]) : '';
  if (rubro && !/^(?:chatbot|web|catalogo|pack)$/i.test(rubro)) fields.business_type = canonicalBusiness(rubro);

  if (/^(?:ventas?|vender mas)$/.test(text)) fields.project_goal = 'ventas';
  else if (/^(?:atencion|atender|servicio al cliente)$/.test(text)) fields.project_goal = 'atención';
  else if (/^(?:catalogo|mostrar productos?)$/.test(text)) fields.project_goal = 'catalogo';
  else if (/^(?:seguimiento|hacer seguimiento)$/.test(text)) fields.project_goal = 'seguimiento';
  else if (!context.project_goal) {
    const goal = pickMatch(raw, [/(?:quiero|necesito|busco)\s+(?:mejorar|aumentar|organizar|automatizar)\s+(.{2,100})/i]);
    if (goal && !/responder|contestar/i.test(goal)) fields.project_goal = clean(goal).slice(0, 120);
  }

  if (/\b(?:pierdo|perdemos)\s+ventas?\b/.test(text)) {
    fields.impact = 'Pierdo ventas';
    fields.pain_point = raw.slice(0, 180);
  } else if (/\b(?:problema|dificultad|se complica|no respondo|respondo tarde|demoramos|no alcanzamos)\b/.test(text)) {
    fields.pain_point = raw.slice(0, 180);
  }

  if (/\b(?:manualmente|por whatsapp|en excel|a mano|una persona responde|respondemos)\b/.test(text)) {
    fields.current_process = raw.slice(0, 180);
  }

  // Así escribe la gente por WhatsApp: un párrafo con el rubro, el objetivo, el
  // problema y el precio todo junto. Aprovechar solo el rubro obliga a volver a
  // preguntar lo que el cliente acaba de contar, que es justo lo que lo pierde.
  //
  // Se parte en cláusulas y cada campo se queda con la suya. Guardar el mensaje
  // entero en tres campos deja un resumen ilegible; guardar la cláusula deja
  // "quiero una pagina para vender online", que es lo que el cliente dijo.
  //
  // Solo para mensajes largos: en uno corto, "quiero la propuesta" acabaría
  // guardado como objetivo del proyecto.
  if (raw.length >= 45) {
    const clausulas = raw
      .split(/[,;.\n]+| y (?=[a-záéíóúñ])| porque | ya que /i)
      .map((parte) => clean(parte))
      .filter((parte) => parte.length >= 6);
    // Una cláusula solo puede alimentar un campo: si no, el objetivo y el
    // proceso acaban siendo la misma frase repetida dos veces en el resumen.
    const usadas = new Set();
    const buscar = (patron, excluir) => {
      for (const parte of clausulas) {
        if (usadas.has(parte)) continue;
        if (!patron.test(normalized(parte))) continue;
        if (excluir && excluir.test(parte)) continue;
        usadas.add(parte);
        return parte.slice(0, 180);
      }
      return '';
    };

    if (!context.project_goal && !fields.project_goal) {
      const meta = buscar(
        /\b(?:quiero|quisiera|necesito|busco|me gustaria)\b/,
        /\b(?:propuesta|cotizaci[oó]n|precio|informaci[oó]n|asesor|hablar con)\b/i,
      );
      if (meta) fields.project_goal = meta.slice(0, 120);
    }
    if (!context.pain_point && !fields.pain_point) {
      const dolor = buscar(
        /\b(?:se (?:me |nos )?pierden|se (?:me |nos )?pierde|se (?:me |nos )?caen|se acumulan|no doy abasto|no alcanzo|no alcanzamos|no me da tiempo|tardo|tardamos|se me pasan|no contesto a tiempo)\b/,
      );
      if (dolor) fields.pain_point = dolor;
    }
    if (!context.current_process && !fields.current_process) {
      const proceso = buscar(
        /\b(?:por instagram|por facebook|por telefono|por el celular|por mensajes directos|por dm|contesto yo|respondo yo|atiendo yo|lo hago yo|la recepcionista|mi equipo|una persona del equipo)\b/,
      );
      if (proceso) fields.current_process = proceso;
    }
  }

  if (/\b(?:quiero|necesito)\s+(?:responder|contestar)\s+mas\s+rapido\b|\bno perder ventas\b|\bautomatizar la atencion\b/.test(text)) {
    fields.desired_outcome = raw.slice(0, 180);
  }

  if (/\b(?:urgente|hoy|esta semana|cuanto antes|lo antes posible)\b/.test(text)) {
    fields.discovery_urgency = /hoy|urgente|cuanto antes|lo antes posible/.test(text) ? 'alta' : 'media';
  }

  for (const clave of Object.keys(fields)) {
    if (clave !== 'email') fields[clave] = sinGritos(fields[clave]);
  }
  return fields;
}

function interpretMessage(input) {
  const source = input && typeof input === 'object' ? input : {};
  const message = clean(source.user_message || source.message || '');
  const context = source.context && typeof source.context === 'object'
    ? source.context
    : (() => { try { return JSON.parse(source.context_json || '{}'); } catch { return {}; } })();
  const intent = detectIntent(message, clean(source.message_type || 'text').toLowerCase());
  const extracted_fields = extractFields(message, context);

  // Red de seguridad: si acabamos de preguntar por un campo de descubrimiento y
  // ninguna regla lo reconoció, se toma la respuesta literal del cliente. Sin
  // esto el decisor vuelve a hacer la misma pregunta, y lo hace indefinidamente.
  // Solo aplica con intención 'general': un "cuánto cuesta" o un "quiero un
  // asesor" no son la respuesta a la pregunta, y el decisor ya sabe atenderlos.
  // No se usa last_question_code: esa columna no existe en el CRM, así que
  // siempre llega vacía. El campo que se acaba de preguntar se deduce igual que
  // lo hace el decisor: es el primero de la secuencia que sigue sin llenar.
  const ORDEN_DESCUBRIMIENTO = [
    'business_type',
    'project_goal',
    'pain_point',
    'current_process',
    'impact',
    'desired_outcome',
  ];
  const campoPendiente = ORDEN_DESCUBRIMIENTO.find((campo) => {
    if (campo === 'impact') return !clean(context.impact) && !clean(context.discovery_urgency);
    return !clean(context[campo]);
  });
  // Una pregunta no es la respuesta a la pregunta. Sin esto, un "¿y qué
  // incluye?" acaba guardado como el rubro del negocio en el CRM.
  // Una pregunta no es la respuesta a la pregunta, y una cortesía tampoco.
  // Sin esto, un "y qué incluye" acaba guardado como rubro del negocio y un
  // "ok gracias" como el objetivo del proyecto.
  const normalizado = normalized(message);
  const arranque = String(message).trim();
  const esPregunta =
    /[?¿]/.test(message) ||
    /^(?:y|o|pero|entonces|oye|ah|pues)?\s*(?:qué|cuál|cómo|cuánto|cuándo|dónde|quién|por qué)(?![a-záéíóúüñ])/i.test(
      arranque,
    ) ||
    /^(?:y|o|pero|entonces|oye|ah|pues)?\s*(?:cual|cuanto|cuando|donde|quien|por que)\b/.test(
      normalizado,
    );
  const soloEmoji = /\p{Extended_Pictographic}/u.test(message) && !/[a-záéíóúüñ]/i.test(message);
  const esCortesia = soloEmoji || /^(?:ok|oki|listo|vale|perfecto|gracias|dale|bueno|si|no|claro|de acuerdo|buenas?|hola)[\s!.]*$|^(?:ok|listo|vale|dale)\s+(?:gracias|perfecto|listo)[\s!.]*$/.test(
    normalizado,
  );
  const pareceRespuesta =
    message.length >= 3 &&
    /[a-z]{3}/.test(normalizado) &&
    !esPregunta &&
    !esCortesia &&
    // Cinco consonantes seguidas no forman una palabra en español: es el
    // teclado aporreado. Sin esto, "asdfgh" acaba en el CRM como rubro.
    !/[bcdfghjklmnpqrstvwxyz]{5}/.test(normalizado);
  if (
    intent === 'general' &&
    campoPendiente &&
    pareceRespuesta &&
    !clean(extracted_fields[campoPendiente]) &&
    !clean(context[campoPendiente])
  ) {
    // "no tengo correo" o "no tengo whatsapp" no describen el negocio: son
    // la ausencia de un dato de contacto, y guardarlos ensucia el CRM.
    const niegaContacto = /\bno (?:tengo|uso|manejo)\s+(?:mi\s+|un\s+|el\s+)?(?:correo|email|e-mail|mail|whatsapp|telefono|celular|numero)\b/.test(normalizado);
    if (!niegaContacto) extracted_fields[campoPendiente] = sinGritos(message.slice(0, 160));
  }

  if (intent === 'select_chatbot' || intent === 'confirm_chatbot') extracted_fields.selected_solution = 'chatbot_whatsapp_ia';
  if (intent === 'select_web' || intent === 'confirm_web') extracted_fields.selected_solution = 'web_catalogo';
  if (intent === 'select_pack') extracted_fields.selected_solution = 'pack_web_chatbot';

  const explicit = intent !== 'general' || Object.keys(extracted_fields).length > 0;
  const ambiguous_fields = [];
  if (!message) ambiguous_fields.push('message');
  if (intent === 'general' && message.length <= 2) ambiguous_fields.push('intent');
  if (extracted_fields.business_type && extracted_fields.business_type.length < 3) ambiguous_fields.push('business_type');

  return {
    intent,
    confidence: explicit ? 0.96 : (message.length > 8 ? 0.58 : 0.35),
    extracted_fields,
    ambiguous_fields,
    reason_code: explicit ? 'DETERMINISTIC_MATCH' : 'AMBIGUOUS_REQUIRES_INTERPRETATION',
    needs_ai: !explicit && message.length > 2,
    is_question: esPregunta,
    is_courtesy: esCortesia,
  };
}


const input = $input.first()?.json || {};
const result = interpretMessage({ ...input, context_json: input.context_json || '{}' });
return [{ json: { intent: result.intent, confidence: result.confidence, extracted_fields: result.extracted_fields, ambiguous_fields: result.ambiguous_fields, reason_code: result.reason_code, needs_ai: result.needs_ai, is_question: result.is_question === true, is_courtesy: result.is_courtesy === true, source_hash: String(input.source_hash || ''), environment: String(input.environment || 'staging') } }];
